from fastapi import FastAPI, APIRouter
from starlette.staticfiles import StaticFiles
import os

# --- Test FastAPI ---
def test_fastapi_frontend():
    app = FastAPI()

    # Test case 1: Valid path and directory
    try:
        app.frontend("/static", "./static")
        print("FastAPI frontend call successful for valid inputs.")
    except Exception as e:
        print(f"FastAPI frontend call failed for valid inputs: {e}")

    # Test case 2: Empty path (should likely fail or behave predictably)
    try:
        app.frontend("", "./static")
        print("FastAPI frontend call successful for empty path.")
    except Exception as e:
        print(f"FastAPI frontend call failed for empty path (Expected behavior if mount fails): {e}")

# --- Test APIRouter ---
def test_apirouter_frontend():
    router = APIRouter()

    # Test case 1: Valid path and directory
    try:
        router.frontend("/static", "./static")
        print("APIRouter frontend call successful for valid inputs.")
    except Exception as e:
        print(f"APIRouter frontend call failed for valid inputs: {e}")

    # Test case 2: Empty path
    try:
        router.frontend("", "./static")
        print("APIRouter frontend call successful for empty path.")
    except Exception as e:
        print(f"APIRouter frontend call failed for empty path (Expected behavior if mount fails): {e}")

if __name__ == "__main__":
    test_fastapi_frontend()
    test_apirouter_frontend()

